    LANGUAGE_WRAPPER = 'In a math contest, {alpha} students explore a parametric family of series. Fix integers q={q}, m={m}, base={base}, and an offset r={offset_r}. Let A be the residue set modulo m given by [allowed_residues]. For each rational x of the form x=k/q where k is an integer with 0 <= k <= q-1, define F(x) as the infinite sum over n >= 1 of base^{-n} for those indices n with floor(n*x + r/q) taken modulo m lying in A. Let L_max be the largest real number such that F(x) >= L for every admissible x=k/q. Determine the largest integer strictly less than {multiplier_k} * L_max.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

