    # c_n = 1 if floor((n*k + r)/q) % m in allowed
    # Use integer arithmetic to keep exactness.
    c = []
    for n in range(1, T+1):
        floor_val = ((n * k) + offset_r) // q
        res = floor_val % m
        c.append(1 if res in allowed else 0)
    # Exact sum over the infinite geometric repetition:
    # S_int = sum_{n=1}^T c_n * base^{T-n}
    # D = base^T - 1
    # F = S_int / D
    # Compute big integers exactly.
    S_int = 0
    pow_cache = 1  # will hold base^{T-n} via forward build if preferred
    # Efficiently compute via accumulating powers
    # Precompute base^{T} then divide by base each step could be heavy; we instead build S_int directly.
    # We'll compute powers decreasing: base^{T-1}, base^{T-2}, ..., base^{0}
    # Start with p = base^{T-1}
    p = pow(base, T-1)
    for idx, ci in enumerate(c):
        # idx from 0..T-1 corresponds to n=1..T, exponent T-n = T-1-idx
        if ci:
            S_int += p
        # Move to next lower power
        if p > 1:
            p //= base
        else:
