    num, den = compute_value_for_k(k)
    if min_num is None:
        min_num, min_den = num, den
    else:
        # Compare num/den with min_num/min_den without floating ops
        # num/den < min_num/min_den iff num*min_den < min_num*den
        if num * min_den < min_num * den:
            min_num, min_den = num, den
